        private void Log(string msg)
        {
            Dispatcher.Invoke(() =>
            {
                string t = DateTime.Now.ToString("HH:mm:ss");
                txtLog.AppendText(string.Format("[{0}] {1}\r\n", t, msg));
                scrollerLog.ScrollToEnd();
            });
        }

        private void SetStatus(string s)
        {
            Dispatcher.Invoke(() => lblStatus.Text = "⚡  " + s);
        }

        private void StartAction(bool isUpdate)
        {
            if (isWorking) return;
            string target = txtPath.Text.Trim();
            if (string.IsNullOrEmpty(target))
            {
                MessageBox.Show("Please choose a target directory.", "Hermes", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            isWorking = true;
            btnInstall.IsEnabled = false;
            btnUpdate.IsEnabled  = false;
            progBar.IsIndeterminate = true;

            bool withGui      = chkFullGui.IsChecked    == true;
            bool withShortcut = chkStartMenu.IsChecked  == true;

            Thread worker = new Thread(() =>
            {
                try   { ExecuteAction(target, isUpdate, withGui, withShortcut); }
                catch (Exception ex)
                {
                    Log("ERROR: " + ex.Message);
                    SetStatus("Failed: " + ex.Message);
                    Dispatcher.Invoke(() =>
                        MessageBox.Show("Error:\n" + ex.Message, "Hermes", MessageBoxButton.OK, MessageBoxImage.Error));
                }
                finally
                {
                    Dispatcher.Invoke(() =>
                    {
                        isWorking = false;
                        btnInstall.IsEnabled = true;
                        btnUpdate.IsEnabled  = true;
                        progBar.IsIndeterminate = false;
                    });
                }
            });
            worker.IsBackground = true;
            worker.Start();
        }

        private void ExecuteAction(string target, bool isUpdate, bool withGui, bool withShortcut)
        {
            Directory.CreateDirectory(target);
            string hermesHome     = System.IO.Path.Combine(target, "hermes_data");
            string hermesAgentDir = System.IO.Path.Combine(target, "hermes-agent");
            string toolsDir       = System.IO.Path.Combine(target, "tools");
            string uvBinDir       = System.IO.Path.Combine(toolsDir, "uv");
            string gitBinDir      = System.IO.Path.Combine(toolsDir, "git");
            string cacheDir       = System.IO.Path.Combine(target, "cache");
            string pythonDir      = System.IO.Path.Combine(toolsDir, "python");
            string venvDir        = System.IO.Path.Combine(target, ".venv");

            foreach (string d in new[]{ hermesHome, toolsDir, uvBinDir, cacheDir, pythonDir,
                                        System.IO.Path.Combine(cacheDir, "temp") })
                Directory.CreateDirectory(d);

            Environment.SetEnvironmentVariable("HERMES_HOME",           hermesHome);
            Environment.SetEnvironmentVariable("HERMES_RUNTIME_DIR",    toolsDir);
            Environment.SetEnvironmentVariable("UV_CACHE_DIR",          System.IO.Path.Combine(cacheDir, "uv"));
            Environment.SetEnvironmentVariable("UV_PYTHON_INSTALL_DIR", pythonDir);
            Environment.SetEnvironmentVariable("TEMP",                  System.IO.Path.Combine(cacheDir, "temp"));
            Environment.SetEnvironmentVariable("TMP",                   System.IO.Path.Combine(cacheDir, "temp"));

            // 1. uv
            string uvExe = System.IO.Path.Combine(uvBinDir, "uv.exe");
            if (!File.Exists(uvExe))
            {
                SetStatus("Downloading portable uv manager...");
                Log("Fetching uv standalone binary...");
                string uvZip = System.IO.Path.Combine(cacheDir, "uv.zip");
                DownloadFile("https://github.com/astral-sh/uv/releases/latest/download/uv-x86_64-pc-windows-msvc.zip", uvZip);
                ZipFile.ExtractToDirectory(uvZip, uvBinDir);
                File.Delete(uvZip);
                Log("uv manager installed.");
            }
            string currentPath = Environment.GetEnvironmentVariable("Path") ?? "";
            Environment.SetEnvironmentVariable("Path", uvBinDir + ";" + currentPath);

            // 2. MinGit
            string gitExe = System.IO.Path.Combine(gitBinDir, "cmd\\git.exe");
            string dummy1;
            bool hasGit = RunCommand("git", "--version", out dummy1) == 0;
            if (!hasGit && !File.Exists(gitExe))
            {
                SetStatus("Downloading portable MinGit...");
                Log("Fetching MinGit...");
                try
                {
                    string gitZip = System.IO.Path.Combine(cacheDir, "mingit.zip");
                    DownloadFile("https://github.com/git-for-windows/git/releases/download/v2.48.1.windows.1/MinGit-2.48.1-64-bit.zip", gitZip);
                    ZipFile.ExtractToDirectory(gitZip, gitBinDir);
                    File.Delete(gitZip);
                    Log("MinGit installed.");
                }
                catch { Log("MinGit fallback to zip archive..."); }
            }
            if (File.Exists(gitExe))
                Environment.SetEnvironmentVariable("Path",
                    System.IO.Path.Combine(gitBinDir, "cmd") + ";" + Environment.GetEnvironmentVariable("Path"));

            // 3. Repo clone or update
            SetStatus("Fetching Hermes Agent repository...");
            if (!Directory.Exists(System.IO.Path.Combine(hermesAgentDir, ".git")))
            {
                Log("Cloning NousResearch/hermes-agent...");
                string cloneOut;
                int res = RunCommand("git", string.Format("clone --depth 1 https://github.com/NousResearch/hermes-agent.git \"{0}\"", hermesAgentDir), out cloneOut);
                if (res != 0)
                {
                    Log("Git clone error. Fetching archive...");
                    string zipFile = System.IO.Path.Combine(cacheDir, "hermes.zip");
                    DownloadFile("https://github.com/NousResearch/hermes-agent/archive/refs/heads/main.zip", zipFile);
                    string extDir = System.IO.Path.Combine(cacheDir, "ext");
                    ZipFile.ExtractToDirectory(zipFile, extDir);
                    string[] sub = Directory.GetDirectories(extDir);
                    if (sub.Length > 0) Directory.Move(sub[0], hermesAgentDir);
                    Directory.Delete(extDir, true);
                    File.Delete(zipFile);
                }
                Log("Hermes Agent source ready.");
            }
            else
            {
                Log("Updating existing repository to latest...");
                string dummy2;
                RunCommand("git", string.Format("-C \"{0}\" pull origin main", hermesAgentDir), out dummy2);
                Log("Repository updated.");
            }

            // 4. Python 3.14 via uv
            SetStatus("Provisioning isolated Python 3.14...");
            Log("Installing Python 3.14 runtime via uv...");
            string dummy3;
            RunCommand(uvExe, "python install 3.14", out dummy3);

            SetStatus("Configuring virtual environment...");
            Log("Creating .venv with Python 3.14...");
            string dummy4;
            RunCommand(uvExe, string.Format("venv \"{0}\" --python 3.14 --clear", venvDir), out dummy4);

            string pythonVenvExe = System.IO.Path.Combine(venvDir, "Scripts\\python.exe");
            SetStatus("Installing Hermes dependencies...");
            Log("Installing packages via uv pip install -e...");
            string pipOut;
            RunCommand(uvExe, string.Format("pip install -e \"{0}\" --python \"{1}\"", hermesAgentDir, pythonVenvExe), out pipOut);
            Log("Python packages synced successfully.");

            // 5. Config dirs & .env
            SetStatus("Preparing local configurations...");
            foreach (string sub in new[]{ "cron","sessions","logs","pairing","hooks","image_cache","audio_cache","memories","skills","bin" })
                Directory.CreateDirectory(System.IO.Path.Combine(hermesHome, sub));

            string envFile = System.IO.Path.Combine(hermesHome, ".env");
            if (!File.Exists(envFile))
            {
                string exEnv = System.IO.Path.Combine(hermesAgentDir, ".env.example");
                if (File.Exists(exEnv)) File.Copy(exEnv, envFile);
                else File.WriteAllText(envFile, "# Hermes Config\r\n");
            }
            string cfgFile = System.IO.Path.Combine(hermesHome, "config.yaml");
            if (!File.Exists(cfgFile))
            {
                string exCfg = System.IO.Path.Combine(hermesAgentDir, "cli-config.yaml.example");
                if (File.Exists(exCfg)) File.Copy(exCfg, cfgFile);
            }

            // 6. Launchers
            SetStatus("Generating portable launchers...");
            string hermesBat = System.IO.Path.Combine(target, "Hermes.bat");
            File.WriteAllText(hermesBat, "@echo off\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nset \"HERMES_HOME=%~dp0hermes_data\"\r\nset \"HERMES_RUNTIME_DIR=%~dp0tools\"\r\nset \"UV_CACHE_DIR=%~dp0cache\\uv\"\r\nset \"UV_PYTHON_INSTALL_DIR=%~dp0tools\\python\"\r\nset \"PATH=%~dp0tools\\uv;%~dp0tools\\git\\cmd;%~dp0.venv\\Scripts;%PATH%\"\r\nif \"%~1\"==\"\" (\r\n    \"%~dp0.venv\\Scripts\\hermes.exe\"\r\n) else (\r\n    \"%~dp0.venv\\Scripts\\hermes.exe\" %*\r\n)\r\npause\r\nendlocal\r\n");

            string setupBat = System.IO.Path.Combine(target, "Setup.bat");
            File.WriteAllText(setupBat, "@echo off\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nset \"HERMES_HOME=%~dp0hermes_data\"\r\nset \"HERMES_RUNTIME_DIR=%~dp0tools\"\r\nset \"PATH=%~dp0tools\\uv;%~dp0tools\\git\\cmd;%~dp0.venv\\Scripts;%PATH%\"\r\n\"%~dp0.venv\\Scripts\\hermes.exe\" setup --portal\r\npause\r\nendlocal\r\n");

            try
            {
                string currentExe = Process.GetCurrentProcess().MainModule.FileName;
                File.Copy(currentExe, System.IO.Path.Combine(target, "Hermes-Setup-Updater.exe"), true);
            }
            catch { }

            // 7. Desktop GUI
            if (withGui)
            {
                SetStatus("Downloading full Desktop GUI...");
                Log("Fetching Hermes Desktop companion...");
                try
                {
                    string guiExe = System.IO.Path.Combine(target, "HermesDesktop.exe");
                    DownloadFile("https://github.com/fathah/hermes-desktop/releases/download/v0.7.7/hermes-desktop-0.7.7-portable.exe", guiExe);
                    string guiBat = System.IO.Path.Combine(target, "Hermes-GUI.bat");
                    File.WriteAllText(guiBat, "@echo off\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nset \"HERMES_HOME=%~dp0hermes_data\"\r\nstart \"\" \"%~dp0HermesDesktop.exe\"\r\nendlocal\r\n");
                    Log("Desktop GUI installed.");
                }
                catch (Exception gEx) { Log("GUI download warning: " + gEx.Message); }
            }

            // 8. Shortcuts
            if (withShortcut)
            {
                SetStatus("Configuring Start Menu shortcuts...");
                CreateShortcuts(target, hermesBat, setupBat);
                Log("Shortcuts added to Start Menu.");
            }

            SetStatus("Operation completed successfully!");
            Log("SUCCESS: Hermes Agent Portable is ready.");
            Dispatcher.Invoke(() =>
                MessageBox.Show(
                    "Hermes Agent Portable ready in:\n" + target +
                    "\n\nLaunch with Hermes.bat or Setup.bat.\nUpdate later with Hermes-Setup-Updater.exe.",
                    "Hermes — Completed", MessageBoxButton.OK, MessageBoxImage.Information));
        }

        private void DownloadFile(string url, string dest)
        {
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12 | (SecurityProtocolType)3072;
            using (WebClient wc = new WebClient())
            {
                wc.Headers.Add("User-Agent", "Hermes-Installer/2.0");
                wc.DownloadFile(url, dest);
            }
        }

        private int RunCommand(string exe, string args, out string output)
        {
            ProcessStartInfo psi = new ProcessStartInfo
            {
                FileName               = exe,
                Arguments              = args,
                RedirectStandardOutput = true,
                RedirectStandardError  = true,
                UseShellExecute        = false,
                CreateNoWindow         = true
            };
            using (Process p = Process.Start(psi))
            {
                output = p.StandardOutput.ReadToEnd() + "\n" + p.StandardError.ReadToEnd();
                p.WaitForExit();
                return p.ExitCode;
            }
        }

        private void CreateShortcuts(string target, string hermesBat, string setupBat)
        {
            try
            {
                string programs = Environment.GetFolderPath(Environment.SpecialFolder.Programs);
                string folder   = System.IO.Path.Combine(programs, "Hermes Agent Portable");
                Directory.CreateDirectory(folder);

                Type shellType  = Type.GetTypeFromProgID("WScript.Shell");
                dynamic shell   = Activator.CreateInstance(shellType);

                dynamic sc1 = shell.CreateShortcut(System.IO.Path.Combine(folder, "Hermes Agent CLI.lnk"));
                sc1.TargetPath = hermesBat; sc1.WorkingDirectory = target; sc1.Save();

                dynamic sc2 = shell.CreateShortcut(System.IO.Path.Combine(folder, "Hermes Agent Setup.lnk"));
                sc2.TargetPath = setupBat; sc2.WorkingDirectory = target; sc2.Save();

                string updaterExe = System.IO.Path.Combine(target, "Hermes-Setup-Updater.exe");
                if (File.Exists(updaterExe))
                {
                    dynamic sc3 = shell.CreateShortcut(System.IO.Path.Combine(folder, "Hermes Installer and Updater.lnk"));
                    sc3.TargetPath = updaterExe; sc3.WorkingDirectory = target; sc3.Save();
                }

                string guiBat = System.IO.Path.Combine(target, "Hermes-GUI.bat");
                if (File.Exists(guiBat))
                {
                    dynamic sc4 = shell.CreateShortcut(System.IO.Path.Combine(folder, "Hermes Desktop GUI.lnk"));
                    sc4.TargetPath = guiBat; sc4.WorkingDirectory = target; sc4.Save();
                }
            }
            catch { }
        }
    }

public static class ArtworkData
    {
        public static string Base64 = "";
    }
}
